#pragma once

#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

namespace faf::editor
{
  /**
   * One function a map script can call (doc/EdLuaApiTable.inc, generated by tools/editor/gen_lua_api.py from FAF's
   * annotated engine Lua at a pinned commit and the game's scenario libraries): its owner (a class such as "Unit",
   * a module alias such as "ScenarioUtils", or "" for a global), name, parameters with their types, return type and
   * description.
   */
  struct EdLuaApiEntry
  {
    const char* owner;
    const char* name;
    const char* params;
    const char* returns;
    const char* doc;
  };

  [[nodiscard]] const std::vector<EdLuaApiEntry>& LuaApi();

  /** A global (owner "") or an owner's function by name, or null. */
  [[nodiscard]] const EdLuaApiEntry* LuaApiFind(std::string_view owner, std::string_view name);

  /** "Name(params) -> returns", the owner's "Owner." or "Owner:" in front when it has one. */
  [[nodiscard]] std::string LuaSignature(const EdLuaApiEntry& entry);

  /** The word being typed before `cursor`: its letters so far, and what is before a `.` or `:` in front of it. */
  struct EdLuaWord
  {
    std::string qualifier; // "ScenarioUtils" in `ScenarioUtils.Cre`, "unit" in `unit:Get`, else ""
    char separator = 0;    // '.', ':' or 0
    std::string prefix;    // "Cre", "Get"
    std::size_t start = 0; // where the prefix starts in the text
  };
  [[nodiscard]] EdLuaWord LuaWordBefore(std::string_view text, std::size_t cursor);

  /**
   * What to offer for a word: after `Module.` the module's functions, after `x:` the methods of every class (the
   * variable's class isn't known), else the globals and the module aliases; those whose names start with the prefix
   * (case aside) first, then those containing it; at most `max`.
   */
  [[nodiscard]] std::vector<const EdLuaApiEntry*> LuaCompletions(const EdLuaWord& word, std::size_t max);

  /** The innermost call the cursor is inside the parentheses of: its function and which argument (0-based). */
  struct EdLuaCall
  {
    std::string qualifier;
    char separator = 0;
    std::string name;
    int argument = 0;
  };
  /** False when the cursor isn't inside a call's parentheses. */
  bool LuaCallAt(std::string_view text, std::size_t cursor, EdLuaCall& call);

  /** The entry a call names (a global, an owner's function, or any class's method after `:`), or null. */
  [[nodiscard]] const EdLuaApiEntry* LuaApiForCall(std::string_view qualifier, char separator, std::string_view name);

  /**
   * A likely typo: a global call the text doesn't define (`function Name`, `local Name`, `Name =`), that isn't Lua's
   * own or a known function, and is one or two letters from a known global (`CreatUnitHPR`): where, and the
   * suggestion.
   */
  struct EdLuaTypo
  {
    std::size_t at = 0;
    int line = 0; // 1-based
    std::string written;
    std::string suggestion;
  };
  [[nodiscard]] std::vector<EdLuaTypo> LuaTypos(std::string_view text);

  /** Letters to change, add or remove to turn one name into the other (case counts). */
  [[nodiscard]] int EditDistance(std::string_view a, std::string_view b);
} // namespace faf::editor
